// Programmatically add difficulty-based achievements
const DIFFICULTIES = Object.values(Difficulty);
const MILESTONES = [
    { count: 1, type: 'bronze', reward: 5 },
    { count: 10, type: 'silver', reward: 25 },
    { count: 50, type: 'gold', reward: 100 },
    { count: 100, type: 'diamond', reward: 250 }
];

DIFFICULTIES.forEach(diff => {
    const safeId = diff.replace(/\s+/g, '').toLowerCase();

    // Win Milestones
    MILESTONES.forEach(m => {
        ACHIEVEMENTS.push({
            id: `win_${safeId}_${m.count}`,
            title: `${diff} ${m.count === 1 ? 'Victory' : (m.count === 10 ? 'Dedication' : (m.count === 50 ? 'Expertise' : 'Mastery'))}`,
            description: `Win ${m.count} level${m.count > 1 ? 's' : ''} on ${diff} difficulty.`,
            icon: Icons.Flame,
            type: m.type as any,
            reward: m.reward,
            requiredWins: m.count, // Explicitly set target for progress bars
            condition: (stats, data) => {
                if (!data) return false;
                // Count wins for this specific difficulty
                const wins = Object.values(data.progress).filter(p => 
                    p.difficulty === diff && (p.status === 'completed' || p.bestTime !== undefined)
                ).length;
                return wins >= m.count;
            }
        });
    });

    // Pack Unlock Milestones
    ACHIEVEMENTS.push({
        id: `unlock_${safeId}_pack2`,
        title: `${diff} Explorer`,
        description: `Unlock Levels 101-200 for ${diff}.`,
        icon: Icons.Unlock,
        type: 'silver',
        reward: 50,
        condition: (stats, data) => data?.unlockedPack2?.includes(diff) ?? false
    });

    ACHIEVEMENTS.push({
        id: `unlock_${safeId}_pack3`,
        title: `${diff} Pioneer`,
        description: `Unlock Levels 201-300 for ${diff}.`,
        icon: Icons.Unlock,
        type: 'gold',
        reward: 100,
        condition: (stats, data) => data?.unlockedPack3?.includes(diff) ?? false
    });
});

export function formatTimeShort(totalSeconds: number) {
    const total = Math.floor(totalSeconds);
    const mins = Math.floor(total / 60);
    const secs = total % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

