                                {sortedAchievements.map(ach => (
                                    <AchievementCard 
                                        key={ach.id} 
                                        ach={ach} 
                                        isUnlocked={!!achievements[ach.id]}
                                        isClaimed={claimedAchievements.includes(ach.id)}
                                        unlockedAt={achievements[ach.id]}
                                        progress={getAchievementProgress(ach, storedData)}
                                        onClaim={handleClaimAchievement}
                                    />
                                ))}
                            </div>

                            {/* Padding bottom */}
                            <div className="h-4" />
                        </div>
                    )}

                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useRef } from 'react';
import { Difficulty, Achievement, LevelProgress, StoredData } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { formatTimeShort, getDifficultyPoints, ACHIEVEMENTS } from '../../utils/constants';
import { sounds } from '../../utils/sound';

interface StatsScreenProps {
    onBack: () => void;
    onEarnPoints?: (amount: number, source?: HTMLElement | DOMRect | null) => void;
    points: number;
}

interface AchievementCardProps { 
    ach: Achievement; 
    isUnlocked: boolean; 
    isClaimed: boolean;
    unlockedAt?: number;
    progress?: { current: number, target: number } | null;
    onClaim: (id: string, reward: number, rect: DOMRect) => void;
}

const AchievementCard: React.FC<AchievementCardProps> = ({ ach, isUnlocked, isClaimed, unlockedAt, progress, onClaim }) => {
    const [expanded, setExpanded] = useState(false);
    const cardRef = useRef<HTMLButtonElement>(null);

    // Status Logic
    const isClaimable = isUnlocked && !isClaimed;

    // Gradient definitions for unlocked state
    const bgClass = isUnlocked 
        ? (ach.type === 'gold' 
            ? 'bg-gradient-to-br from-yellow-100 to-amber-200 border-amber-300 dark:from-yellow-900/40 dark:to-amber-900/40 dark:border-amber-700' 
            : ach.type === 'silver'
            ? 'bg-gradient-to-br from-slate-100 to-slate-200 border-slate-300 dark:from-slate-800 dark:to-slate-900 dark:border-slate-700'
            : ach.type === 'diamond'
            ? 'bg-gradient-to-br from-cyan-100 to-blue-200 border-blue-300 dark:from-cyan-900/40 dark:to-blue-900/40 dark:border-blue-700'
            : 'bg-gradient-to-br from-orange-100 to-orange-200 border-orange-300 dark:from-orange-900/40 dark:to-orange-900/40 dark:border-orange-700') // bronze
        : 'bg-stone-100 border-stone-200 dark:bg-stone-800/50 dark:border-stone-700 grayscale';

    const Icon = ach.icon;

    const handleClick = (e: React.MouseEvent) => {
        if (isClaimable) {
            e.stopPropagation();
            if (cardRef.current) {
                const rect = cardRef.current.getBoundingClientRect();
                onClaim(ach.id, ach.reward, rect);
            }
        } else {
            sounds.playClick();
            setExpanded(!expanded);
        }
    };

    // Calculate progress percentage if locked and progress available
    let progressPercent = 0;
    if (progress && !isUnlocked) {
        progressPercent = Math.min(100, (progress.current / progress.target) * 100);
    }

    return (
        <button 
            ref={cardRef}
            onClick={handleClick}
            className={`w-full text-left p-4 rounded-2xl border transition-all duration-300 relative overflow-hidden group ${bgClass} ${expanded ? 'shadow-md scale-[1.02]' : 'shadow-sm active:scale-[0.98]'}`}
        >
            <div className="flex items-center gap-4 relative z-10">
                <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 shadow-inner ${isUnlocked ? 'bg-white/40 dark:bg-black/20 text-stone-800 dark:text-stone-100' : 'bg-stone-200 dark:bg-stone-700 text-stone-400'}`}>
                    <Icon className="w-6 h-6" />
                </div>
                <div className="flex-1 min-w-0">
                    <h3 className={`font-bold text-base leading-tight ${isUnlocked ? 'text-stone-900 dark:text-white' : 'text-stone-500'}`}>{ach.title}</h3>
                    <p className={`text-xs font-medium leading-tight mt-0.5 ${isUnlocked ? 'text-stone-700 dark:text-stone-300' : 'text-stone-400'}`}>
                        {isUnlocked ? ach.description : "Locked"}
                    </p>
                </div>

                {/* Reward / Status Badge */}
                <div className="shrink-0 flex flex-col items-end gap-1">
                     {isClaimed ? (
                         <div className="w-6 h-6 bg-white/50 rounded-full flex items-center justify-center">
                             <Icons.Check className="w-4 h-4 text-green-600 dark:text-green-400" />
                         </div>
                     ) : isClaimable ? (
                         <div className="flex items-center gap-1.5 bg-white shadow-sm border border-blue-100 px-3 py-1.5 rounded-xl animate-pulse">
                             <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">Claim</span>
                             <div className="flex items-center gap-0.5">
                                <span className="text-[10px] font-bold text-stone-800">+{ach.reward}</span>
                                <Icons.Diamond className="w-2.5 h-2.5 text-blue-500 fill-current" />
                             </div>
                         </div>
                     ) : (
                         <div className="flex items-center gap-1 bg-black/5 dark:bg-white/10 px-2 py-1 rounded-lg">
                             <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400">+{ach.reward}</span>
                             <Icons.Diamond className="w-2.5 h-2.5 text-stone-400 fill-current" />
                         </div>
                     )}
                </div>
            </div>

            {/* Expanded Details */}
            <div className={`overflow-hidden transition-all duration-300 ${expanded ? 'max-h-32 opacity-100 mt-3 pt-3 border-t border-black/5 dark:border-white/5' : 'max-h-0 opacity-0'}`}>
                 <div className="flex justify-between items-center text-[10px] font-bold uppercase tracking-wider text-stone-500 dark:text-stone-400 mb-2">
                     <span className="flex items-center gap-1">
                         {ach.type} Badge
                         {isClaimed && (
                             <span className="ml-2 text-blue-500 flex items-center gap-0.5">
                                 +{ach.reward} <Icons.Diamond className="w-2.5 h-2.5 fill-current" />
                             </span>
                         )}
                     </span>
                     {isUnlocked && unlockedAt && (
                         <span>Unlocked {new Date(unlockedAt).toLocaleDateString()}</span>
                     )}
                 </div>

                 {!isUnlocked && (
                     <>
                        <p className="text-xs text-stone-500 dark:text-stone-400 italic mb-3">
                            {ach.description}
                        </p>

                        {/* Progress Bar moved here */}
                        {progress && (
                            <div className="w-full">
                                <div className="flex justify-between text-[9px] font-bold text-stone-400 mb-1">
                                    <span>Progress</span>
                                    <span>{progress.current} / {progress.target}</span>
                                </div>
                                <div className="h-2 w-full bg-stone-200 dark:bg-stone-700 rounded-full overflow-hidden">
                                    <div className="h-full bg-blue-500/70 rounded-full transition-all duration-500" style={{ width: `${progressPercent}%` }}></div>
                                </div>
                            </div>
                        )}
                     </>
                 )}
            </div>
        </button>
    );
};

export const StatsScreen: React.FC<StatsScreenProps> = ({ onBack, onEarnPoints, points }) => {
    const [activeTab, setActiveTab] = useState<'stats' | 'achievements'>('stats');

    // Stats State
    const [selectedDiff, setSelectedDiff] = useState<Difficulty>(Difficulty.Normal);
    const [isDiffMenuOpen, setIsDiffMenuOpen] = useState(false);

    // Load Data
    const [storedData, setStoredData] = useState(Storage.getStoredData());

    const achievements = storedData.achievements || {};
    const claimedAchievements = storedData.claimedAchievements || [];

    const unlockedCount = Object.keys(achievements).length;
    const totalAchievements = ACHIEVEMENTS.length;

    const claimableCount = Object.keys(achievements).filter(id => !claimedAchievements.includes(id)).length;

    const handleClaimAchievement = (id: string, reward: number, rect: DOMRect) => {
        sounds.playBubblePop(); // Satisfying claim sound

        // Update Storage
        Storage.claimAchievement(id);

        // Trigger Visuals
        if (onEarnPoints) {
            onEarnPoints(reward, rect);
        }

        // Refresh local state
        setStoredData(Storage.getStoredData());
    };

    // Derived Stats
    const stats = useMemo(() => {
        const allProgress = storedData.progress;
        const result = {
            completed: 0,
            totalTime: 0,
            bestTime: Infinity,
        };

        Object.values(allProgress).forEach((p: LevelProgress) => {
            if (p.difficulty === selectedDiff && (p.status === 'completed' || p.bestTime !== undefined)) {
                result.completed++;
                const timeToAdd = p.bestTime !== undefined ? p.bestTime : p.timeElapsed;
                result.totalTime += timeToAdd;
                if (p.bestTime && p.bestTime < result.bestTime) {
                    result.bestTime = p.bestTime;
                }
            }
        });
        return result;
    }, [selectedDiff, storedData]);

    const averageTime = stats.completed > 0 ? Math.floor(stats.totalTime / stats.completed) : 0;
    const pointsPerGame = getDifficultyPoints(selectedDiff);
    const totalDiamondsEarned = stats.completed * pointsPerGame;

    const formatFullTime = (seconds: number) => {
        const total = Math.floor(seconds);
        const h = Math.floor(total / 3600);
        const m = Math.floor((total % 3600) / 60);
        const s = total % 60;
        const mStr = m.toString().padStart(2, '0');
        const sStr = s.toString().padStart(2, '0');
        if (h > 0) return `${h}h ${mStr}m ${sStr}s`;
        return `${mStr}m ${sStr}s`;
    };

    const getAchievementProgress = (ach: Achievement, data: StoredData) => {
        if (!data.stats) return null;

        let current = 0;
        let target = 0;

        if (ach.requiredWins) {
            target = ach.requiredWins;
            // Check if it's a specific difficulty achievement based on ID pattern
            if (ach.id.startsWith('win_')) {
                 const diffPart = ach.id.split('_')[1];
                 const match = Object.values(Difficulty).find(d => d.replace(/\s+/g, '').toLowerCase() === diffPart);

                 if (match) {
                     current = Object.values(data.progress).filter(p => 
                        p.difficulty === match && (p.status === 'completed' || p.bestTime !== undefined)
                     ).length;
                 } else {
                     current = data.stats.totalGamesWon;
                 }
            } else {
                 current = data.stats.totalGamesWon;
            }
        } else if (ach.requiredEarnings) {
            target = ach.requiredEarnings;
            current = data.stats.totalDiamondsEarned;
        } else if (ach.requiredPerfectGames) {
            target = ach.requiredPerfectGames;
            current = data.stats.perfectGames;
        } else {
            return null;
        }

        return { current, target };
    };

    // Sort achievements: Claimable -> Locked -> Claimed
    const sortedAchievements = [...ACHIEVEMENTS].sort((a, b) => {
        const aUnlocked = !!achievements[a.id];
        const aClaimed = claimedAchievements.includes(a.id);
        const aClaimable = aUnlocked && !aClaimed;

        const bUnlocked = !!achievements[b.id];
        const bClaimed = claimedAchievements.includes(b.id);
        const bClaimable = bUnlocked && !bClaimed;

        // 1. Claimable at top
        if (aClaimable && !bClaimable) return -1;
        if (!aClaimable && bClaimable) return 1;

        // 2. Locked in middle (unlocked is false)
        // If 'a' is unlocked (claimed) and 'b' is locked -> b comes first
        if (!aUnlocked && bUnlocked) return -1;
        if (aUnlocked && !bUnlocked) return 1;

        // 3. Claimed at bottom
        // (Handled naturally by the above logic as the last remaining group)

        return 0;
    });

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            {/* Header */}
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-4 pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Profile</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">My Journey</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm relative z-30">
                      <div id="points-pill" className="contents">
                        <span className="text-sm font-bold text-t-primary">{points}</span>
                        <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                      </div>
                </div>
            </div>

            {/* Segmented Control */}
            <div className="w-full max-w-md px-6 mb-4 shrink-0">
                <div className="bg-stone-200 dark:bg-stone-800 p-1 rounded-2xl flex relative">
                    {/* Sliding Background */}
                    <div 
                        className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white dark:bg-stone-600 rounded-xl shadow-sm transition-transform duration-300 ease-out ${activeTab === 'achievements' ? 'translate-x-[calc(100%+4px)]' : 'translate-x-0'}`}
                    />

                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex-1 py-2.5 text-sm font-bold relative z-10 transition-colors ${activeTab === 'stats' ? 'text-stone-900 dark:text-white' : 'text-stone-500 hover:text-stone-700 dark:text-stone-400'}`}
                    >
                        Statistics
                    </button>
                    <button 
                        onClick={() => setActiveTab('achievements')}
                        className={`flex-1 py-2.5 text-sm font-bold relative z-10 transition-colors ${activeTab === 'achievements' ? 'text-stone-900 dark:text-white' : 'text-stone-500 hover:text-stone-700 dark:text-stone-400'}`}
                    >
                        Achievements
                        {claimableCount > 0 && (
                            <span className="absolute top-2 right-4 w-2 h-2 bg-red-500 rounded-full" />
                        )}
                    </button>
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                <div className="w-full max-w-md pt-2">

                    {activeTab === 'stats' ? (
                        <div className="animate-fade-in space-y-4">
                            {/* Difficulty Selector */}
                            <div className="w-full z-20">
                                <button 
                                    onClick={() => { sounds.playClick(); setIsDiffMenuOpen(!isDiffMenuOpen); }}
                                    className="w-full bg-t-surface p-4 rounded-2xl shadow-sm flex items-center justify-between active:scale-[0.98] transition-all relative z-10"
                                >
                                    <span className="text-lg font-bold text-t-primary">{selectedDiff}</span>
                                    <Icons.Back className={`w-5 h-5 text-t-secondary transition-transform duration-300 ${isDiffMenuOpen ? '-rotate-90' : '-rotate-180'}`} /> 
                                </button>

                                <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isDiffMenuOpen ? 'max-h-[400px] opacity-100 mt-2' : 'max-h-0 opacity-0 mt-0'}`}>
                                    <div className="bg-t-surface rounded-2xl shadow-sm overflow-hidden flex flex-col">
                                        {Object.values(Difficulty).map((diff) => (
                                            <button
                                                key={diff}
                                                onClick={() => { sounds.playClick(); setSelectedDiff(diff); setIsDiffMenuOpen(false); }}
                                                className={`w-full text-left px-5 py-4 text-lg font-bold border-b border-stone-200 dark:border-stone-700 last:border-0 hover:bg-stone-50 dark:hover:bg-stone-800 transition-colors ${selectedDiff === diff ? 'text-blue-500 bg-blue-50/50 dark:bg-blue-900/10' : 'text-t-primary'}`}
                                            >
                                                {diff}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            {/* Big Stats Grid */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-t-surface p-6 rounded-3xl shadow-sm flex flex-col items-center text-center">
                                    <div className="w-12 h-12 bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400 rounded-full flex items-center justify-center mb-3">
                                        <Icons.Check className="w-6 h-6 stroke-[3]" />
                                    </div>
                                    <span className="text-3xl font-bold text-t-primary mb-1">{stats.completed}</span>
                                    <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Solved</span>
                                </div>

                                <div className="bg-t-surface p-6 rounded-3xl shadow-sm flex flex-col items-center text-center">
